begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
grant usage on schema extensions to authenticated;
grant execute on all functions in schema extensions to authenticated;
select extensions.no_plan();

insert into auth.users(id) values ('00000000-0000-0000-0000-000000987703');
insert into public.profiles(id, display_name) values ('00000000-0000-0000-0000-000000987703', 'Analyzer receipt integrity admin');
insert into public.user_roles(user_id, role_id)
select '00000000-0000-0000-0000-000000987703', id from public.roles where key = 'admin';

create temporary table analyzer_receipt_payload(payload jsonb);
insert into analyzer_receipt_payload values ('{
  "fingerprint":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
  "delivery_id":"1111111111111111111111111111111111111111111111111111111111111111",
  "raw_input":"0x0000000000000000000000000000000000000001",
  "input_type":"CONTRACT_ADDRESS",
  "requested_chain":"ethereum",
  "resolution":{"inputType":"CONTRACT_ADDRESS","source":"direct-input","chain":"ethereum","tokenAddress":"0x0000000000000000000000000000000000000001","canonicalTokenId":"ethereum:0x0000000000000000000000000000000000000001","pairAddress":null,"poolAddress":null,"symbol":null,"name":null,"decimals":null,"supply":null,"launchpad":null,"creator":null,"creationTimestamp":null,"programOrContract":null,"confidence":"CANDIDATE_IDENTITY","provenance":[]},
  "manifest":{"schemaVersion":"token-analyzer-v1","manifestFormatVersion":1,"evidenceRevision":1,"capturedAt":"2026-09-20T00:00:00Z","input":{"type":"CONTRACT_ADDRESS","rawHash":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"},"resolvedToken":{"inputType":"CONTRACT_ADDRESS","source":"direct-input","chain":"ethereum","tokenAddress":"0x0000000000000000000000000000000000000001","canonicalTokenId":"ethereum:0x0000000000000000000000000000000000000001","pairAddress":null,"poolAddress":null,"symbol":null,"name":null,"decimals":null,"supply":null,"launchpad":null,"creator":null,"creationTimestamp":null,"programOrContract":null,"confidence":"CANDIDATE_IDENTITY","provenance":[]},"observations":[],"claims":[],"providerConflicts":[],"missing":[],"freshness":{"state":"UNKNOWN","reason":"No explicit freshness policy is available."},"methodologyVersion":null},
  "result":{"requestId":"00000000-0000-0000-0000-000000000000","status":"INSUFFICIENT_DATA","input":{"raw":"0x0000000000000000000000000000000000000001","hintChain":"ethereum"},"resolvedToken":{"inputType":"CONTRACT_ADDRESS","source":"direct-input","chain":"ethereum","tokenAddress":"0x0000000000000000000000000000000000000001","canonicalTokenId":"ethereum:0x0000000000000000000000000000000000000001","pairAddress":null,"poolAddress":null,"symbol":null,"name":null,"decimals":null,"supply":null,"launchpad":null,"creator":null,"creationTimestamp":null,"programOrContract":null,"confidence":"CANDIDATE_IDENTITY","provenance":[]},"chain":"ethereum","pair":{"address":null,"pool":null},"freshness":{"state":"UNKNOWN","reason":"No explicit freshness policy is available."},"dataConfidence":{"state":"UNKNOWN","coverage":0,"reason":"No evidence."},"evidenceSummary":{"total":0,"available":0,"unknown":0,"sources":[]},"score":{"value":null,"max":100,"methodologyVersion":null,"status":"METHODOLOGY_NOT_ACTIVE","components":{"marketStructure":null,"liquidityQuality":null,"distribution":null,"activity":null,"authorityRisk":null,"creatorRisk":null,"manipulationRisk":null,"dataQuality":null}},"market":{},"liquidity":{},"holders":{},"creator":{},"activity":{},"topTrades":[],"whyMoving":[],"claimVerification":[],"riskFactors":[],"unknowns":[],"positionSizing":{"status":"POSITION_SIZE_UNAVAILABLE","riskBudget":null,"stopDistancePercent":null,"positionNotional":null,"reason":"No inputs."},"aiInterpretation":{"status":"DISABLED","provider":null,"model":null,"content":null},"citations":[],"providerConflicts":[],"methodologyVersion":null,"schemaVersion":"token-analyzer-v1","createdAt":"2026-09-20T00:00:00Z"},
  "status":"INSUFFICIENT_DATA","schema_version":"token-analyzer-v1","analysis_mode":"DETERMINISTIC","freshness_class":"UNKNOWN","freshness_expires_at":"2000-01-01T00:00:00Z","identity":{"chain":"ethereum","canonicalTokenId":"ethereum:0x0000000000000000000000000000000000000001","inputType":"CONTRACT_ADDRESS","pairAddress":null,"poolAddress":null,"schemaVersion":"token-analyzer-v1","methodologyVersion":null,"scoreEngineVersion":null,"analysisMode":"DETERMINISTIC"},"operation":"DELIVERY_RETRY"
}'::jsonb);
grant select, update on analyzer_receipt_payload to authenticated;

select set_config('request.jwt.claims', '{"sub":"00000000-0000-0000-0000-000000987703","role":"authenticated"}', true);
select set_config('request.jwt.claim.sub', '00000000-0000-0000-0000-000000987703', true);
set local role authenticated;
set local search_path = public, extensions;
select public.set_token_analyzer_enabled(true);

select extensions.is((select public.analyzer_submit_run(payload)->>'analysis_version' from analyzer_receipt_payload), '1'::text, 'Initial sealed delivery creates version one'::text);
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,score,components,marketStructure}', '99'::jsonb, true))$$, '23P01', null, 'Non-null component score is rejected while methodology is inactive');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{resolution,tokenAddress}', '"0x0000000000000000000000000000000000000002"', true), '{manifest,resolvedToken,tokenAddress}', '"0x0000000000000000000000000000000000000002"', true))$$, '23P01', null, 'Canonical token identity mismatch is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{schema_version}', '"made-up-schema-v999"', true))$$, '23P01', null, 'Invented schema version is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,liquidity}', '{"value":"999999999"}'::jsonb, true))$$, '23P01', null, 'Unsupported nested liquidity result is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,claimVerification}', '[{"verification":"SUPPORTED","evidenceRefs":["missing"],"evidenceType":"VERIFIED_DATA","field":"liquidity","identity":"pool-1","source":"chain","value":"1"}]'::jsonb, true))$$, '23P01', null, 'Nonexistent claim evidence is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,whyMoving}', '[{"classification":"VERIFIED_DATA","evidenceRefs":["missing"],"explanation":"unsupported"}]'::jsonb, true))$$, '23P01', null, 'Nonexistent explanation evidence is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,riskFactors}', '[{"key":"liquidity","state":"PRESENT","evidenceRefs":["missing"],"explanation":"unsupported"}]'::jsonb, true))$$, '23P01', null, 'Nonexistent risk evidence is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,topTrades}', '[{"evidenceId":"missing","key":"trade","value":"999"}]'::jsonb, true))$$, '23P01', null, 'Nonexistent trade evidence is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{manifest,observations}', '[{"evidenceId":"liquidity-1","state":"AVAILABLE","key":"liquidity","source":"chain","evidenceClass":"VERIFIED_DATA","identity":"pool-1","value":"100","provenance":[{"source":"chain","kind":"DIRECT_CHAIN","reference":"pool-1"}] }]'::jsonb, true), '{result,topTrades}', '[{"evidenceId":"liquidity-1","key":"trade","value":"999"}]'::jsonb, true))$$, '23P01', null, 'Trade evidence cannot reuse a liquidity observation with changed identity or value');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,pair,address}', '"0x0000000000000000000000000000000000000002"'::jsonb, true))$$, '23P01', null, 'Conflicting pair identity is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{manifest,manifestFormatVersion}', 'null'::jsonb, true))$$, '23P01', null, 'Omitted manifest format version is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set((select payload from analyzer_receipt_payload), '{result,score,methodologyVersion}', '"made-up-methodology"'::jsonb, true))$$, '23P01', null, 'Nested methodology version is rejected');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{fingerprint}', '"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"'::jsonb, true), '{raw_input}', '"0x0000000000000000000000000000000000000001"'::jsonb, true), '{resolution,tokenAddress}', '"0x0000000000000000000000000000000000000002"'::jsonb, true))$$, '23P01', null, 'Raw input cannot resolve to a different result token');
select extensions.throws_ok($$select public.analyzer_submit_run(jsonb_set(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{fingerprint}', '"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"'::jsonb, true), '{raw_input}', '"not-an-address"'::jsonb, true), '{resolution,tokenAddress}', '"not-an-address"'::jsonb, true))$$, '23P01', null, 'Invalid address cannot persist with a caller-consistent canonical ID');
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"FRESH_ANALYSIS"', true), '{delivery_id}', '"2222222222222222222222222222222222222222222222222222222222222222"', true))->>'analysis_version'), '2'::text, 'Fresh analysis appends version two'::text);
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"EXPLICIT_REANALYSIS"', true), '{reanalysis_reason}', '"receipt test"', true), '{delivery_id}', '"3333333333333333333333333333333333333333333333333333333333333333"', true))->>'analysis_version'), '3'::text, 'Explicit reanalysis appends version three'::text);
select extensions.is((select public.analyzer_submit_run((select payload from analyzer_receipt_payload))->>'analysis_version'), '1'::text, 'Delivery D1 retry returns sealed version one'::text);
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"DELIVERY_RETRY"', true), '{delivery_id}', '"2222222222222222222222222222222222222222222222222222222222222222"', true))->>'analysis_version'), '2'::text, 'Delivery D2 retry returns sealed version two'::text);
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"DELIVERY_RETRY"', true), '{delivery_id}', '"3333333333333333333333333333333333333333333333333333333333333333"', true))->>'analysis_version'), '3'::text, 'Delivery D3 retry returns sealed version three'::text);
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"FRESH_ANALYSIS"', true), '{delivery_id}', '"4444444444444444444444444444444444444444444444444444444444444444"', true))->>'analysis_version'), '4'::text, 'Same manifest can have a distinct sealed delivery'::text);
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"DELIVERY_RETRY"', true), '{delivery_id}', '"4444444444444444444444444444444444444444444444444444444444444444"', true))->>'analysis_version'), '4'::text, 'Distinct same-manifest delivery retries exactly'::text);
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"FRESH_ANALYSIS"', true), '{delivery_id}', '"5555555555555555555555555555555555555555555555555555555555555555"', true), '{manifest,capturedAt}', '"2026-09-21T00:00:00Z"', true))->>'analysis_version'), '5'::text, 'Changed capture time creates its own delivery'::text);
select extensions.is((select public.analyzer_submit_run(jsonb_set(jsonb_set(jsonb_set((select payload from analyzer_receipt_payload), '{operation}', '"DELIVERY_RETRY"', true), '{delivery_id}', '"5555555555555555555555555555555555555555555555555555555555555555"', true), '{manifest,capturedAt}', '"2026-09-21T00:00:00Z"', true))->>'analysis_version'), '5'::text, 'Changed capture-time delivery retries exactly'::text);
select extensions.is((select public.analyzer_get_delivery_receipt('2222222222222222222222222222222222222222222222222222222222222222')->>'analysis_version'), '2'::text, 'Exact delivery receipt lookup returns D2'::text);
select extensions.is((select public.analyzer_get_analysis_by_version(((public.analyzer_get_delivery_receipt('2222222222222222222222222222222222222222222222222222222222222222')->>'request_id')::uuid), 1)->>'analysis_version'), '1'::text, 'Historical lookup returns the requested analysis version'::text);
select extensions.is((select public.analyzer_get_latest_analysis(((public.analyzer_get_delivery_receipt('2222222222222222222222222222222222222222222222222222222222222222')->>'request_id')::uuid))->>'analysis_version'), '5'::text, 'Latest lookup is explicit and returns the latest version'::text);
reset role;
select extensions.is((select result->>'analysisVersion' from public.analyzer_analyses where request_id = (select id from public.analyzer_requests where request_fingerprint = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa') and analysis_version = 1), '1'::text, 'Embedded analysis version matches relational version'::text);
select extensions.is((select count(*) from public.analyzer_analyses where request_id = (select id from public.analyzer_requests where request_fingerprint = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa')), 5::bigint, 'Delivery retries do not create additional analyses'::text);
select extensions.is((select evidence_revision from public.analyzer_analyses where request_id = (select id from public.analyzer_requests where request_fingerprint = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa') and analysis_version = 5), 2, 'Evidence revision is derived for changed evidence'::text);
select extensions.is((select (m.manifest->>'evidenceRevision')::integer from public.analyzer_evidence_manifests m join public.analyzer_analyses a on a.evidence_manifest_id = m.id where a.request_id = (select id from public.analyzer_requests where request_fingerprint = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa') and a.analysis_version = 5), 2, 'Embedded manifest revision matches stored evidence revision'::text);
select extensions.is((select (result->>'evidenceRevision')::integer from public.analyzer_analyses where request_id = (select id from public.analyzer_requests where request_fingerprint = 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa') and analysis_version = 5), 2, 'Embedded result revision matches relational evidence revision'::text);

reset role;
select * from extensions.finish(true);
rollback;
